-- Frozen schema23 DDL and HTTP-generated OEM requirement/receipt/IQC rows.
-- Provenance: git archive 56e2c51, historical WorkflowHarness.material_requirement(), create_project mode overridden to OEM,
-- historical WorkflowStore initialized SCHEMA_VERSION=23; sqlite3.Connection.iterdump().
-- No version rewriting and no schema24 DDL. Captured 2026-11-09.
BEGIN TRANSACTION;
CREATE TABLE acceptance_issues(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),shipment_id TEXT NOT NULL REFERENCES shipments(id),fact_id TEXT NOT NULL REFERENCES delivery_facts(id),title TEXT NOT NULL,owner_id TEXT NOT NULL,owner_name TEXT NOT NULL,required INTEGER NOT NULL);
CREATE TABLE acceptance_resolutions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),issue_id TEXT NOT NULL UNIQUE REFERENCES acceptance_issues(id),evidence TEXT NOT NULL,actor_id TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE allocation_adjustments(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),order_line_id TEXT NOT NULL REFERENCES order_lines(id),work_order_id TEXT NOT NULL REFERENCES work_orders(id),delta_atoms INTEGER NOT NULL,switch_id TEXT NOT NULL REFERENCES eco_switches(id));
CREATE TABLE allocations(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), order_line_id TEXT NOT NULL REFERENCES order_lines(id), work_order_id TEXT NOT NULL, q_atoms INTEGER NOT NULL CHECK(q_atoms>0), unit TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE arrival_matches(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,project_id TEXT NOT NULL REFERENCES projects(id),arrival_id TEXT NOT NULL REFERENCES arrivals(id),receipt_id TEXT NOT NULL REFERENCES supply_receipts(id),payload_json TEXT NOT NULL);
CREATE TABLE arrivals(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,project_id TEXT NOT NULL REFERENCES projects(id),payload_json TEXT NOT NULL);
CREATE TABLE asset_uses(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),npi_id TEXT NOT NULL REFERENCES npis(id),asset_revision_id TEXT NOT NULL REFERENCES reusable_assets(id),revision INTEGER NOT NULL,snapshot_json TEXT NOT NULL,required INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(npi_id,asset_revision_id));
CREATE TABLE asset_verifications(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,project_id TEXT NOT NULL REFERENCES projects(id),asset_use_id TEXT NOT NULL REFERENCES asset_uses(id),payload_json TEXT NOT NULL);
CREATE TABLE audit_events(id INTEGER PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), actor_id TEXT NOT NULL, action TEXT NOT NULL, object_id TEXT NOT NULL, occurred_at TEXT NOT NULL, recorded_at TEXT NOT NULL, typed_payload TEXT NOT NULL);
