CREATE TABLE authority_rules(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,project_id TEXT NOT NULL REFERENCES projects(id),object_category TEXT NOT NULL,scope_key TEXT NOT NULL,revision INTEGER NOT NULL,payload_json TEXT NOT NULL,UNIQUE(project_id,object_category,scope_key,revision));
CREATE TABLE authority_verifications(rule_id TEXT PRIMARY KEY REFERENCES authority_rules(id),project_id TEXT NOT NULL REFERENCES projects(id),payload_json TEXT NOT NULL);
CREATE TABLE calibrations(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,project_id TEXT NOT NULL REFERENCES projects(id),payload_json TEXT NOT NULL,confirmation_json TEXT);
CREATE TABLE capa_steps(seq INTEGER PRIMARY KEY AUTOINCREMENT,project_id TEXT NOT NULL REFERENCES projects(id),capa_id TEXT NOT NULL REFERENCES capas(id),step TEXT NOT NULL,payload_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE capas(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,project_id TEXT NOT NULL REFERENCES projects(id),rma_id TEXT NOT NULL UNIQUE REFERENCES rmas(id),state TEXT NOT NULL CHECK(state IN ('open','closed')),created_at TEXT NOT NULL);
CREATE TABLE change_impacts(change_id TEXT NOT NULL REFERENCES commitment_changes(id), project_id TEXT NOT NULL REFERENCES projects(id), object_type TEXT NOT NULL, object_id TEXT NOT NULL, q_atoms INTEGER NOT NULL, unit TEXT NOT NULL, decision TEXT, evidence TEXT, PRIMARY KEY(change_id,object_type,object_id));
CREATE TABLE closures(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,project_id TEXT NOT NULL REFERENCES projects(id),kind TEXT NOT NULL CHECK(kind IN ('fulfillment','quality','cost')),source_system TEXT NOT NULL,source_type TEXT NOT NULL,source_external_id TEXT NOT NULL,source_json TEXT NOT NULL,evidence TEXT NOT NULL,actor_id TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(source_system,source_type,source_external_id));
CREATE TABLE commitment_changes(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), order_line_id TEXT NOT NULL REFERENCES order_lines(id), old_q_atoms INTEGER NOT NULL, new_q_atoms INTEGER NOT NULL, unit TEXT NOT NULL, old_due TEXT NOT NULL, new_due TEXT NOT NULL, cancel INTEGER NOT NULL, reason TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','applied')), source_version INTEGER NOT NULL, source_json TEXT NOT NULL, created_at TEXT NOT NULL, resolved_at TEXT);
CREATE TABLE component_links(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,project_id TEXT NOT NULL REFERENCES projects(id),unit_id TEXT NOT NULL REFERENCES units(id),material_id TEXT NOT NULL,serial_key TEXT NOT NULL,payload_json TEXT NOT NULL,removal_json TEXT);
CREATE TABLE contract_agreements(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),revision_id TEXT NOT NULL REFERENCES engineering_revisions(id),supersedes_id TEXT UNIQUE REFERENCES contract_agreements(id),contract_json TEXT NOT NULL,customer_id TEXT NOT NULL,external_signatory TEXT NOT NULL,evidence TEXT NOT NULL,project_version INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(project_id,project_version));
CREATE TABLE customer_approvals(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),revision_id TEXT NOT NULL REFERENCES engineering_revisions(id),customer_id TEXT NOT NULL,external_signatory TEXT NOT NULL,method TEXT NOT NULL CHECK(method IN ('manual','file','mock','api')),decision TEXT NOT NULL,evidence TEXT NOT NULL,actor_id TEXT NOT NULL,created_at TEXT NOT NULL,accepted_seq INTEGER NOT NULL);
CREATE TABLE dataset_metadata(id TEXT NOT NULL, mode TEXT NOT NULL, label TEXT NOT NULL);
INSERT INTO "dataset_metadata" VALUES('workflow-test','test','Workflow test');
CREATE TABLE delivery_facts(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,project_id TEXT NOT NULL REFERENCES projects(id),shipment_id TEXT NOT NULL REFERENCES shipments(id),action TEXT NOT NULL CHECK(action IN ('sign','accept')),q_atoms INTEGER NOT NULL CHECK(q_atoms>0),source_system TEXT NOT NULL,source_type TEXT NOT NULL,source_external_id TEXT NOT NULL,source_json TEXT NOT NULL,external_signatory TEXT NOT NULL,actor_id TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(source_system,source_type,source_external_id));
CREATE TABLE demands(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), demand_kind TEXT NOT NULL CHECK(demand_kind IN ('inquiry','forecast','firm')), product TEXT NOT NULL, q_atoms INTEGER NOT NULL CHECK(q_atoms>0), unit TEXT NOT NULL, due_date TEXT NOT NULL, supersedes_demand_id TEXT REFERENCES demands(id), source_system TEXT NOT NULL, source_type TEXT NOT NULL, source_external_id TEXT NOT NULL, source_version INTEGER NOT NULL, source_json TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(source_system,source_type,source_external_id));
INSERT INTO "demands" VALUES('f3312846-3c7b-4c8b-9d2b-d3e4abcc313c','b574c41b-9280-4482-b830-062ede8e0ee2','firm','Camera',5,'piece','2026-12-01',NULL,'erp','demand','demand-f4d26641-cb4a-4dec-98e9-370f79f4e637',1,'{"system":"erp","object_type":"demand","external_id":"demand-f4d26641-cb4a-4dec-98e9-370f79f4e637","version":1,"mode":"manual","occurred_at":"2026-10-28T08:00:00Z","collected_at":"2026-10-28T08:01:00Z","cutoff":"2026-10-28T08:00:00Z","evidence":"manual entry: demand-f4d26641-cb4a-4dec-98e9-370f79f4e637"}','2026-11-09T10:13:05.703869+00:00');
CREATE TABLE eco_changes(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),old_revision_id TEXT NOT NULL REFERENCES engineering_revisions(id),new_revision_id TEXT REFERENCES engineering_revisions(id),work_order_ids_json TEXT NOT NULL,sn_ids_json TEXT NOT NULL,reason TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('open','closed')),created_at TEXT NOT NULL);
CREATE TABLE eco_dispositions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),eco_id TEXT NOT NULL REFERENCES eco_changes(id),impact_id TEXT NOT NULL REFERENCES eco_impacts(id),q_atoms INTEGER NOT NULL CHECK(q_atoms>0),decision TEXT NOT NULL,evidence TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE eco_impacts(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),eco_id TEXT NOT NULL REFERENCES eco_changes(id),payload_json TEXT NOT NULL);
CREATE TABLE eco_retentions(eco_id TEXT NOT NULL REFERENCES eco_changes(id),project_id TEXT NOT NULL REFERENCES projects(id),work_order_id TEXT NOT NULL REFERENCES work_orders(id),q_atoms INTEGER NOT NULL CHECK(q_atoms>0),unit_ids_json TEXT NOT NULL,evidence TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(eco_id,work_order_id));
CREATE TABLE eco_stock_openings(eco_id TEXT NOT NULL REFERENCES eco_changes(id),project_id TEXT NOT NULL REFERENCES projects(id),lot_id TEXT NOT NULL REFERENCES material_lots(id),basis_json TEXT NOT NULL,consumed_atoms INTEGER NOT NULL,complete INTEGER NOT NULL,PRIMARY KEY(eco_id,lot_id));
CREATE TABLE eco_switches(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),eco_id TEXT NOT NULL REFERENCES eco_changes(id),work_order_id TEXT NOT NULL REFERENCES work_orders(id),new_work_order_id TEXT,new_revision_id TEXT REFERENCES engineering_revisions(id),boundary TEXT NOT NULL,q_atoms INTEGER NOT NULL CHECK(q_atoms>0),retained_atoms INTEGER NOT NULL CHECK(retained_atoms>=0),exchange_id TEXT NOT NULL UNIQUE REFERENCES exchanges(id),accepted_receipt_id TEXT UNIQUE,created_at TEXT NOT NULL);
CREATE TABLE engineering_revisions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),package_id TEXT NOT NULL,revision TEXT NOT NULL,customer_revision TEXT NOT NULL,internal_revision TEXT NOT NULL,firmware_version TEXT NOT NULL,test_spec_json TEXT NOT NULL,content_hash TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(project_id,package_id,revision));
INSERT INTO "engineering_revisions" VALUES('8ee613c7-42ce-4ca7-be4f-e084866b03cb','b574c41b-9280-4482-b830-062ede8e0ee2','package-camera','M1','C1','M1','F1','{"measurements":[{"lower":"4","name":"voltage","unit":"V","upper":"6"}],"program_version":"P1","version":"T1"}','b7e252094821491e7016646ffc4c2b0e04cad8e55a1ae22f4c6dbb024f8b9993','2026-11-09T10:13:05.779829+00:00');
CREATE TABLE exchange_discrepancies(seq INTEGER PRIMARY KEY AUTOINCREMENT,exchange_id TEXT NOT NULL REFERENCES exchanges(id),project_id TEXT NOT NULL REFERENCES projects(id),owner_id TEXT NOT NULL,owner_name TEXT NOT NULL,reason TEXT NOT NULL,evidence TEXT NOT NULL,resolves_seq INTEGER REFERENCES exchange_discrepancies(seq));
CREATE TABLE exchange_events(seq INTEGER PRIMARY KEY AUTOINCREMENT,exchange_id TEXT NOT NULL REFERENCES exchanges(id),project_id TEXT NOT NULL REFERENCES projects(id),phase TEXT NOT NULL,reason TEXT NOT NULL,payload_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE exchange_receipts(seq INTEGER PRIMARY KEY AUTOINCREMENT,exchange_id TEXT NOT NULL REFERENCES exchanges(id),project_id TEXT NOT NULL REFERENCES projects(id),receipt_id TEXT NOT NULL,payload_json TEXT NOT NULL,valid INTEGER NOT NULL,reason TEXT NOT NULL,UNIQUE(exchange_id,receipt_id,payload_json));
CREATE TABLE exchanges(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,project_id TEXT NOT NULL REFERENCES projects(id),reservation_id TEXT REFERENCES reservations(id),action TEXT NOT NULL,policy_action TEXT NOT NULL,system TEXT NOT NULL,business_key TEXT NOT NULL UNIQUE,mode TEXT NOT NULL,request_json TEXT NOT NULL,request_hash TEXT NOT NULL,phase TEXT NOT NULL,attempted INTEGER NOT NULL DEFAULT 0,reason TEXT NOT NULL DEFAULT '',receipt_json TEXT,source_sequence INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE execution_admissions(event_id TEXT PRIMARY KEY REFERENCES execution_events(id),project_id TEXT NOT NULL REFERENCES projects(id),admitted INTEGER NOT NULL,record_json TEXT NOT NULL,claimed_correction_id TEXT);
CREATE TABLE execution_events(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),work_order_id TEXT NOT NULL REFERENCES work_orders(id),unit_id TEXT REFERENCES units(id),claimed_sn TEXT NOT NULL,source_system TEXT NOT NULL,source_type TEXT NOT NULL,source_external_id TEXT NOT NULL,source_version INTEGER NOT NULL,source_json TEXT NOT NULL,station TEXT NOT NULL,route_version TEXT NOT NULL,program_version TEXT NOT NULL,firmware_version TEXT NOT NULL,result TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('accepted','rejected')),reason TEXT NOT NULL,route_kind TEXT NOT NULL CHECK(route_kind IN ('initial','rework')),rework_order_id TEXT,supersedes_event_id TEXT REFERENCES execution_events(id),occurred_at TEXT NOT NULL,recorded_at TEXT NOT NULL,accepted_seq INTEGER NOT NULL);
CREATE TABLE execution_exceptions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),work_order_id TEXT NOT NULL REFERENCES work_orders(id),interruption_id TEXT NOT NULL UNIQUE REFERENCES interruptions(id),kind TEXT NOT NULL CHECK(kind IN ('S3','S4','other')),reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE first_articles(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),work_order_id TEXT NOT NULL REFERENCES work_orders(id),revision_id TEXT NOT NULL REFERENCES engineering_revisions(id),route_fingerprint TEXT NOT NULL,test_version TEXT NOT NULL,program_version TEXT NOT NULL,firmware_version TEXT NOT NULL,equipment_check_id TEXT NOT NULL REFERENCES readiness_checks(id),inspection_id TEXT NOT NULL,test_ids_json TEXT NOT NULL,unit_ids_json TEXT NOT NULL,accepted_seq INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE freeze_confirmations(project_id TEXT NOT NULL REFERENCES projects(id),object_kind TEXT NOT NULL,object_id TEXT NOT NULL,request_id TEXT NOT NULL REFERENCES freeze_requests(id),state TEXT NOT NULL CHECK(state IN ('frozen','unfrozen')),source_version INTEGER NOT NULL,source_sequence INTEGER NOT NULL,PRIMARY KEY(project_id,object_kind,object_id));
CREATE TABLE freeze_members(request_id TEXT NOT NULL REFERENCES freeze_requests(id),project_id TEXT NOT NULL REFERENCES projects(id),unit_id TEXT REFERENCES units(id),lot_id TEXT REFERENCES material_lots(id),CHECK((unit_id IS NULL)<>(lot_id IS NULL)));
CREATE TABLE freeze_requests(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,project_id TEXT NOT NULL REFERENCES projects(id),exchange_id TEXT NOT NULL UNIQUE REFERENCES exchanges(id),requested_state TEXT NOT NULL CHECK(requested_state IN ('frozen','unfrozen')),source_version INTEGER NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE handoffs(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),revision_id TEXT NOT NULL REFERENCES engineering_revisions(id),to_system TEXT NOT NULL,received_revision TEXT NOT NULL,decision TEXT NOT NULL,status TEXT NOT NULL,evidence TEXT NOT NULL,created_at TEXT NOT NULL,accepted_seq INTEGER NOT NULL);
INSERT INTO "handoffs" VALUES('9d2bad14-b092-4956-bfa2-ec0167e9d827','b574c41b-9280-4482-b830-062ede8e0ee2','8ee613c7-42ce-4ca7-be4f-e084866b03cb','MES','M1','accepted','verified','MES package acknowledgement','2026-11-09T10:13:05.791148+00:00',1);
CREATE TABLE integration_intents(
 id TEXT PRIMARY KEY,
 project_id TEXT NOT NULL REFERENCES projects(id),
 actor_id TEXT NOT NULL,
 system TEXT NOT NULL,
 operation TEXT NOT NULL,
 policy_action TEXT NOT NULL,
 expected_version INTEGER NOT NULL CHECK(expected_version>=1),
 payload_json TEXT NOT NULL,
 payload_hash TEXT NOT NULL,
 phase TEXT NOT NULL CHECK(phase IN ('prepared','pending','unknown','accepted','rejected','applied')),
 created_at TEXT NOT NULL,
 UNIQUE(project_id,id)
);
CREATE TABLE integration_network_cursors(
 project_id TEXT NOT NULL REFERENCES projects(id),
 producer TEXT NOT NULL,
 position INTEGER NOT NULL CHECK(position>=1),
 turn INTEGER NOT NULL CHECK(turn>=1),
 PRIMARY KEY(project_id,producer)
);
CREATE TABLE integration_object_links(
 project_id TEXT NOT NULL REFERENCES projects(id),
 system TEXT NOT NULL,
 object_type TEXT NOT NULL,
 external_id TEXT NOT NULL,
 version INTEGER NOT NULL,
 target_kind TEXT NOT NULL,
 target_id TEXT NOT NULL,
 relation TEXT NOT NULL,
 PRIMARY KEY(project_id,system,object_type,external_id,version,target_kind,target_id,relation),
 FOREIGN KEY(project_id,system,object_type,external_id,version)
 REFERENCES integration_projections(project_id,system,object_type,external_id,version)
);
CREATE TABLE integration_projections(
 project_id TEXT NOT NULL REFERENCES projects(id),
 system TEXT NOT NULL,
 object_type TEXT NOT NULL,
 external_id TEXT NOT NULL,
 version INTEGER NOT NULL CHECK(version>=1),
 payload_hash TEXT NOT NULL,
 fact_json TEXT NOT NULL,
 result_json TEXT NOT NULL,
 projected_at TEXT NOT NULL,
 PRIMARY KEY(project_id,system,object_type,external_id,version)
);
CREATE TABLE integration_receipts(
 project_id TEXT NOT NULL REFERENCES projects(id),
 intent_id TEXT NOT NULL,
 attempt INTEGER NOT NULL CHECK(attempt>=1),
 receipt_json TEXT NOT NULL,
 received_at TEXT NOT NULL,
 PRIMARY KEY(project_id,intent_id,attempt),
 FOREIGN KEY(project_id,intent_id) REFERENCES integration_intents(project_id,id)
);
CREATE TABLE integration_reservation_releases(
 project_id TEXT NOT NULL REFERENCES projects(id),
 system TEXT NOT NULL, object_type TEXT NOT NULL, external_id TEXT NOT NULL, version INTEGER NOT NULL,
 reservation_id TEXT NOT NULL REFERENCES reservations(id),
 qualification_key TEXT NOT NULL, receipt_system TEXT NOT NULL, receipt_external_id TEXT NOT NULL,
 receipt_version INTEGER NOT NULL, q_atoms INTEGER NOT NULL CHECK(q_atoms>0), payload_hash TEXT NOT NULL,
 recorded_at TEXT NOT NULL,
 PRIMARY KEY(project_id,system,object_type,external_id,version,reservation_id,qualification_key),
 FOREIGN KEY(project_id,system,object_type,external_id,version) REFERENCES integration_projections(project_id,system,object_type,external_id,version) DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE integration_return_units(
 project_id TEXT NOT NULL REFERENCES projects(id), system TEXT NOT NULL, object_type TEXT NOT NULL,
 external_id TEXT NOT NULL, version INTEGER NOT NULL, payload_hash TEXT NOT NULL,
 unit_id TEXT NOT NULL REFERENCES units(id), rma_id TEXT NOT NULL UNIQUE REFERENCES rmas(id),
 PRIMARY KEY(project_id,system,object_type,external_id,version,unit_id),
 FOREIGN KEY(project_id,system,object_type,external_id,version) REFERENCES integration_projections(project_id,system,object_type,external_id,version) DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE interruption_actions(seq INTEGER PRIMARY KEY AUTOINCREMENT,project_id TEXT NOT NULL REFERENCES projects(id),interruption_id TEXT NOT NULL REFERENCES interruptions(id),exchange_id TEXT NOT NULL UNIQUE REFERENCES exchanges(id),kind TEXT NOT NULL CHECK(kind IN ('stop','resume')));
CREATE TABLE interruptions(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),work_order_id TEXT NOT NULL REFERENCES work_orders(id),reason TEXT NOT NULL,exception_id TEXT,requested_at TEXT NOT NULL,authority_stopped_at TEXT,resolved_at TEXT,interrupted_plan_id TEXT REFERENCES plans(id),plan_id TEXT REFERENCES plans(id),stop_exchange_id TEXT NOT NULL UNIQUE REFERENCES exchanges(id),resume_exchange_id TEXT UNIQUE REFERENCES exchanges(id),trial_resumed_at TEXT,superseded_by TEXT REFERENCES interruptions(id));
CREATE TABLE iqc_results(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),receipt_id TEXT NOT NULL REFERENCES supply_receipts(id),accepted_atoms INTEGER NOT NULL CHECK(accepted_atoms>=0),rejected_atoms INTEGER NOT NULL CHECK(rejected_atoms>=0),evidence TEXT NOT NULL,actor_id TEXT NOT NULL,created_at TEXT NOT NULL,CHECK(accepted_atoms+rejected_atoms>0));
