CREATE TABLE material_consumption(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),execution_event_id TEXT NOT NULL REFERENCES execution_events(id),unit_id TEXT NOT NULL REFERENCES units(id),lot_id TEXT NOT NULL REFERENCES material_lots(id),material_id TEXT NOT NULL,owner_id TEXT NOT NULL,q_atoms INTEGER NOT NULL CHECK(q_atoms>0),unit TEXT NOT NULL,accepted_seq INTEGER NOT NULL);
CREATE TABLE material_handoffs(
 seq INTEGER PRIMARY KEY AUTOINCREMENT,
 id TEXT NOT NULL UNIQUE,
 project_id TEXT NOT NULL REFERENCES projects(id),
 material_lot_id TEXT NOT NULL REFERENCES material_lots(id),
 work_order_id TEXT REFERENCES work_orders(id),
 sender_id TEXT NOT NULL,
 receiver_id TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('pending','received','disputed','resolved','cancelled')),
 payload_json TEXT NOT NULL,
 receipt_json TEXT,
 resolution_json TEXT,
 cancellation_json TEXT
);
CREATE TABLE material_lots(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),material_id TEXT NOT NULL,lot_id TEXT NOT NULL,owner_id TEXT NOT NULL,unit TEXT NOT NULL,scale INTEGER NOT NULL,expiry TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('active','frozen')),source_system TEXT NOT NULL,source_type TEXT NOT NULL,source_external_id TEXT NOT NULL,source_version INTEGER NOT NULL,source_json TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(project_id,lot_id),UNIQUE(source_system,source_type,source_external_id));
