CREATE TABLE material_movements(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,project_id TEXT NOT NULL REFERENCES projects(id),material_lot_id TEXT NOT NULL REFERENCES material_lots(id),movement TEXT NOT NULL CHECK(movement IN ('return','raw_loss')),q_atoms INTEGER NOT NULL CHECK(q_atoms>0),supersedes_id TEXT UNIQUE REFERENCES material_movements(id),source_system TEXT NOT NULL,source_type TEXT NOT NULL,source_external_id TEXT NOT NULL,source_json TEXT NOT NULL,external_signatory TEXT NOT NULL,evidence TEXT NOT NULL,actor_id TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(source_system,source_type,source_external_id));
CREATE TABLE nonconformances(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,project_id TEXT NOT NULL REFERENCES projects(id),unit_id TEXT NOT NULL REFERENCES units(id),test_id TEXT NOT NULL UNIQUE REFERENCES quality_tests(id),defect TEXT NOT NULL,evidence TEXT NOT NULL,actor_id TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE npi_issue_resolutions(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,project_id TEXT NOT NULL REFERENCES projects(id),issue_id TEXT NOT NULL REFERENCES npi_issues(id),payload_json TEXT NOT NULL);
CREATE TABLE npi_issues(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),npi_id TEXT NOT NULL REFERENCES npis(id),payload_json TEXT NOT NULL,resolution_json TEXT,created_at TEXT NOT NULL);
CREATE TABLE npi_records(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,project_id TEXT NOT NULL REFERENCES projects(id),npi_id TEXT NOT NULL REFERENCES npis(id),record_type TEXT NOT NULL,payload_json TEXT NOT NULL);
CREATE TABLE npi_work_orders(npi_id TEXT NOT NULL REFERENCES npis(id),project_id TEXT NOT NULL REFERENCES projects(id),work_order_id TEXT NOT NULL REFERENCES work_orders(id),PRIMARY KEY(npi_id,work_order_id));
CREATE TABLE npis(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),revision_id TEXT NOT NULL REFERENCES engineering_revisions(id),product_family TEXT NOT NULL,scenario TEXT NOT NULL,required_checks_json TEXT NOT NULL,generation INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE operations(dataset TEXT NOT NULL, actor_id TEXT NOT NULL, operation_id TEXT NOT NULL, payload_hash TEXT NOT NULL, result_json TEXT NOT NULL, PRIMARY KEY(dataset,actor_id,operation_id));
