CREATE TABLE shipment_freeze_events(seq INTEGER PRIMARY KEY AUTOINCREMENT,project_id TEXT NOT NULL REFERENCES projects(id),unit_id TEXT NOT NULL REFERENCES units(id),state TEXT NOT NULL CHECK(state IN ('pending','frozen','released')),source_sequence INTEGER,reference TEXT NOT NULL);
