CREATE VIEW effective_allocations AS SELECT id,project_id,order_line_id,work_order_id,q_atoms,unit,created_at FROM allocations UNION ALL SELECT a.id,a.project_id,a.order_line_id,a.work_order_id,a.delta_atoms,w.unit,s.created_at FROM allocation_adjustments a JOIN work_orders w ON w.id=a.work_order_id JOIN eco_switches s ON s.id=a.switch_id;
